-- AnyBike universal 20-section model system: cross-brand documentary intake.
-- 16 exact unstaged catalogue models, two private research sections each.
-- Factory URLs and original editorial summaries; no pictures, permissions,
-- catalogue identities, public sections, or stock may be changed.
DO $$
DECLARE matched integer; inserted integer; before_public integer; after_public integer;
BEGIN
 SELECT count(*) INTO before_public FROM public.motorcycle_universal_published_sections_v1;
 WITH expected(id,manufacturer,model) AS (VALUES
 (242,'Triumph','Scrambler 1200'),
(250,'Triumph','STREET TRIPLE 765'),
(256,'Triumph','TIGER 900'),
(257,'Triumph','TIGER 900 GT PRO'),
(258,'Triumph','TIGER 900 RALLY PRO'),
(261,'Triumph','TRIDENT 660'),
(520,'KTM','1290 Super Adventure'),
(931,'KTM','890 Duke'),
(7,'Aprilia','TUONO 660'),
(623,'Royal Enfield','Classic 350'),
(624,'Royal Enfield','Continental GT 650'),
(625,'Royal Enfield','Himalayan 411'),
(627,'Royal Enfield','Hunter 350'),
(628,'Royal Enfield','Interceptor 650'),
(629,'Royal Enfield','Meteor 350'),
(229,'Royal Enfield','SUPER METEOR 650')
 )
 SELECT count(*) INTO matched FROM expected e
 JOIN public.motorcycle_catalog_models m
 ON m.id=e.id AND m.manufacturer=e.manufacturer AND m.model=e.model
 WHERE NOT EXISTS(SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s WHERE s.entity_type='model' AND s.model_id=e.id)
 AND NOT EXISTS(SELECT 1 FROM public.motorcycle_catalog_model_aliases a WHERE a.alias_model_id=e.id AND a.review_status<>'approved');
 IF matched<>16 THEN RAISE EXCEPTION 'Private cross-brand intake cancelled: exact ID/staging/alias check found % of 16', matched; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,v.model_id,v.slot,v.title,v.content,
 'draft','official_manufacturer_research:'||v.source_url,NULL
 FROM (VALUES
 (242,1,'Model introduction','{"summary":"Triumph''s Scrambler 1200 extends the modern classic Bonneville family with a dual-purpose, road-and-trail character.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/our-story/brand-timeline","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/our-story/brand-timeline'),
(242,7,'Documented model history','{"summary":"Triumph''s official brand timeline identifies the Scrambler 1200 reveal in 2018, alongside the Speed Twin. Subsequent equipment and model-year variants require separate sources.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/our-story/brand-timeline","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/our-story/brand-timeline'),
(250,1,'Model introduction','{"summary":"The Street Triple 765 developed Triumph''s middleweight naked-roadster family around a new generation of three-cylinder engines.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/our-story/brand-timeline","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/our-story/brand-timeline'),
(250,7,'Documented model history','{"summary":"Triumph documents the Street Triple 765 family launch in 2017. The corporate timeline does not establish trim-specific specifications for every Street Triple 765.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/our-story/brand-timeline","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/our-story/brand-timeline'),
(256,1,'Model introduction','{"summary":"Triumph''s Tiger 900 is the middleweight adventure-touring family, with variants for road and more off-road-oriented use.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system'),
(256,7,'Documented model history','{"summary":"Triumph''s model-year connectivity matrix identifies Tiger 900 GT and Rally equipment from MY20 onward. This is a model-family reference, not a full launch-specification document.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system'),
(257,1,'Model introduction','{"summary":"The Tiger 900 GT Pro is a touring-oriented variant within Triumph''s Tiger 900 adventure family.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system'),
(257,7,'Documented model history','{"summary":"Triumph lists Tiger 900 GT Pro connectivity equipment as original equipment from MY20 onward. This evidence is GT Pro-specific, and later years need their own review.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system'),
(258,1,'Model introduction','{"summary":"The Tiger 900 Rally Pro is the off-road-oriented high-equipment variant in Triumph''s Tiger 900 range.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system'),
(258,7,'Documented model history','{"summary":"Triumph''s published model-year matrix lists Tiger 900 Rally Pro connectivity as original equipment from MY20 onward. Do not copy GT Pro chassis specifications across variants.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/motorcycles/my-triumph-connectivity-system'),
(261,1,'Model introduction','{"summary":"Triumph''s Trident 660 brought a mid-capacity three-cylinder roadster into the company''s contemporary range.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/our-story/brand-timeline","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/our-story/brand-timeline'),
(261,7,'Documented model history','{"summary":"Triumph''s official timeline places the Trident 660 introduction in 2020. Subsequent model-year revisions are outside the scope of this first history draft.","source_name":"Triumph official manufacturer documentation","source_url":"https://www.triumphmotorcycles.co.uk/our-story/brand-timeline","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/our-story/brand-timeline'),
(520,1,'Model introduction','{"summary":"The KTM 1290 Super Adventure family combines a high-capacity V-twin platform with adventure-touring chassis and rider technology.","source_name":"KTM official manufacturer documentation","source_url":"https://press.ktm.com/news-out-now-the-new-ktm-1290-super-adventure-s-ktm-sportmotorcycle-uk?id=123710&imageid=440252&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://press.ktm.com/news-out-now-the-new-ktm-1290-super-adventure-s-ktm-sportmotorcycle-uk?id=123710&imageid=440252&l=uk&menueid=5904'),
(520,7,'Documented model history','{"summary":"KTM''s release documents the third-generation 1290 Super Adventure S arriving for 2021. The source concerns the S variant and must not be treated as universal R or original 1290 Super Adventure specification.","source_name":"KTM official manufacturer documentation","source_url":"https://press.ktm.com/news-out-now-the-new-ktm-1290-super-adventure-s-ktm-sportmotorcycle-uk?id=123710&imageid=440252&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://press.ktm.com/news-out-now-the-new-ktm-1290-super-adventure-s-ktm-sportmotorcycle-uk?id=123710&imageid=440252&l=uk&menueid=5904'),
(931,1,'Model introduction','{"summary":"The KTM 890 Duke developed the parallel-twin middleweight Duke line for roadster riders seeking agile handling.","source_name":"KTM official manufacturer documentation","source_url":"https://press.ktm.com/news-fresh-from-the-grindstone-the-ktm-890-duke-sharpens-the-scalpel?id=123316&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://press.ktm.com/news-fresh-from-the-grindstone-the-ktm-890-duke-sharpens-the-scalpel?id=123316&l=uk&menueid=5904'),
(931,7,'Documented model history','{"summary":"KTM''s January 2021 announcement introduces the standard 890 Duke, following the more track-oriented 890 Duke R in 2020. The standard and R equipment must remain separate.","source_name":"KTM official manufacturer documentation","source_url":"https://press.ktm.com/news-fresh-from-the-grindstone-the-ktm-890-duke-sharpens-the-scalpel?id=123316&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://press.ktm.com/news-fresh-from-the-grindstone-the-ktm-890-duke-sharpens-the-scalpel?id=123316&l=uk&menueid=5904'),
(7,1,'Model introduction','{"summary":"The Tuono 660 is Aprilia''s middleweight roadster based around its compact parallel-twin engineering.","source_name":"Aprilia official manufacturer documentation","source_url":"https://wlassets.aprilia.com/wlassets/aprilia/gb/brochure/2020/EN-DIGITAL-Aprilia-Tuono-660-Brochure-03-2021/original/EN-DIGITAL-Aprilia-Tuono%2B660-Brochure-03-2021.pdf?1614877857594=","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://wlassets.aprilia.com/wlassets/aprilia/gb/brochure/2020/EN-DIGITAL-Aprilia-Tuono-660-Brochure-03-2021/original/EN-DIGITAL-Aprilia-Tuono%2B660-Brochure-03-2021.pdf?1614877857594='),
(7,7,'Documented model history','{"summary":"Aprilia''s March 2021 Tuono 660 brochure documents the launch-era twin-cylinder architecture and riding character. Specifications apply to the brochure configuration, not all later Tuono 660 model years.","source_name":"Aprilia official manufacturer documentation","source_url":"https://wlassets.aprilia.com/wlassets/aprilia/gb/brochure/2020/EN-DIGITAL-Aprilia-Tuono-660-Brochure-03-2021/original/EN-DIGITAL-Aprilia-Tuono%2B660-Brochure-03-2021.pdf?1614877857594=","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://wlassets.aprilia.com/wlassets/aprilia/gb/brochure/2020/EN-DIGITAL-Aprilia-Tuono-660-Brochure-03-2021/original/EN-DIGITAL-Aprilia-Tuono%2B660-Brochure-03-2021.pdf?1614877857594='),
(623,1,'Model introduction','{"summary":"Royal Enfield''s Classic 350 is a traditional-style road motorcycle reflecting the company''s long-running single-cylinder heritage.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf'),
(623,7,'Documented model history','{"summary":"Royal Enfield''s 2022–23 corporate annual report records the debut of its all-new Classic 350 generation in 2021. The history does not establish an original launch date for every earlier Classic iteration.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf'),
(624,1,'Model introduction','{"summary":"The Continental GT 650 is Royal Enfield''s modern twin-cylinder café-racer interpretation of the Continental GT name.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/in/en/our-world/media/news/product-launches/int-650-and-continental-gt-650/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/news/product-launches/int-650-and-continental-gt-650/'),
(624,7,'Documented model history','{"summary":"Royal Enfield describes the Continental GT 650 and Interceptor INT 650 as distinct twin models unveiled together at EICMA on 7 November 2017, ahead of subsequent market launches in 2018.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/in/en/our-world/media/news/product-launches/int-650-and-continental-gt-650/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/news/product-launches/int-650-and-continental-gt-650/'),
(625,1,'Model introduction','{"summary":"Royal Enfield''s original Himalayan brought simple, travel-focused single-cylinder engineering into an accessible adventure model.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/id/id/our-world/media/news/events/royal-enfield-himalayanmakesindonesiadebut2016giias/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/id/id/our-world/media/news/events/royal-enfield-himalayanmakesindonesiadebut2016giias/'),
(625,7,'Documented model history','{"summary":"Royal Enfield''s 2016 Indonesian debut documentation records the early Himalayan with a 411 cc single-cylinder engine. The source is original-generation specific; it does not describe the later Himalayan 450.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/id/id/our-world/media/news/events/royal-enfield-himalayanmakesindonesiadebut2016giias/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/id/id/our-world/media/news/events/royal-enfield-himalayanmakesindonesiadebut2016giias/'),
(627,1,'Model introduction','{"summary":"The Royal Enfield Hunter 350 is a compact, modern-styled roadster within the manufacturer''s 350-family range.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf'),
