(628,1,'Model introduction','{"summary":"The Interceptor 650 is a contemporary Royal Enfield roadster inspired by the company''s earlier twin-cylinder models.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/in/en/our-world/media/news/product-launches/int-650-and-continental-gt-650/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/news/product-launches/int-650-and-continental-gt-650/'),
(628,7,'Documented model history','{"summary":"Royal Enfield''s primary product history documents the unveiling of the Interceptor INT 650 and Continental GT 650 at EICMA on 7 November 2017. Market launches followed in 2018.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/in/en/our-world/media/news/product-launches/int-650-and-continental-gt-650/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/news/product-launches/int-650-and-continental-gt-650/'),
(629,1,'Model introduction','{"summary":"The Meteor 350 is Royal Enfield''s contemporary small-capacity cruiser-style road motorcycle.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf'),
(629,7,'Documented model history','{"summary":"The manufacturer annual report records the new Meteor 350 debut in 2020 and describes an all-new engine and chassis in that generation.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf'),
(229,1,'Model introduction','{"summary":"The Super Meteor 650 is Royal Enfield''s twin-cylinder cruiser within its modern 650 range.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf'),
(229,7,'Documented model history','{"summary":"Royal Enfield''s annual report describes the Super Meteor 650''s EICMA 2022 debut and 2023 launch. The model must remain distinct from the Meteor 350.","source_name":"Royal Enfield official manufacturer documentation","source_url":"https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source-linked private research candidate. All years, market scope, model variants, claims, and photo permissions need editorial review before release."}'::jsonb,'https://www.royalenfield.com/content/dam/eicher-motors/investor/disclosures-under-regulation-46/financial-information/Annual%20Report%20Financial%20Year%202022-23.pdf')
 ) AS v(model_id,slot,title,content,source_url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>32 THEN RAISE EXCEPTION 'Expected 32 private research sections; inserted %',inserted; END IF;
 SELECT count(*) INTO after_public FROM public.motorcycle_universal_published_sections_v1;
 IF after_public<>before_public THEN RAISE EXCEPTION 'Universal public projection unexpectedly changed'; END IF;
END $$;
